SELECT DATE_TRUNC('MONTH', event_time) AS event_month, MAX(duration_sec) AS max_duration_sec, AVG(duration_sec) AS avg_duration_sec, MAX(event_time) AS last_event_time FROM web_events WHERE (event_type = 'add_to_cart' AND duration_sec = 197) OR event_time < '2024-05-21' GROUP BY event_month HAVING AVG(duration_sec) < 400 ORDER BY avg_duration_sec DESC, last_event_time DESC, event_month LIMIT 20;
